  for x in o.get('parameters',[]):print('param',x.get('name'),x.get('in'),x.get('required'),x.get('schema'))
  rb=o.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
  if rb: print('request',json.dumps(rb,separators=(',',':')))
  print('responses', {k:v.get('description','') for k,v in o.get('responses',{}).items()})
PY", "security_risk": "LOW", "summary": "Print endpoint request schemas and status responses", "timeout": 30}

