package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

type Coord struct { Latitude float64 `json:"latitude"`; Longitude float64 `json:"longitude"` }
type User struct { ID string `json:"id"`; Username string `json:"username"`; Password string `json:"password"`; Email string `json:"email,omitempty"`; FullName string `json:"fullName,omitempty"`; Phone string `json:"phone,omitempty"`; Roles []string `json:"roles"`; Qualifications []string `json:"qualifications"`; Certifications []map[string]interface{} `json:"certifications"`; Active bool `json:"active"`; AssignedLocationID string `json:"assignedLocationId,omitempty"`; Available bool `json:"available"`; CapacityUnits int `json:"capacityUnits"`; Location *Coord `json:"location,omitempty"`; LocationAt string `json:"locationAt,omitempty"`; Declines int `json:"declines"` }
type SampleType struct { ID string `json:"id"`; Name string `json:"name"`; Qualified bool `json:"qualifiedCollectorRequired"`; Qualification string `json:"requiredQualification,omitempty"`; Container string `json:"containerType"`; Min float64 `json:"temperatureMinC"`; Max float64 `json:"temperatureMaxC"`; Incompatible []string `json:"incompatibleSampleTypes"`; Cooled bool `json:"requiresCooledRoute"`; Batching bool `json:"batchingAllowed"` }
type Capacity struct { CapacityUnits int `json:"capacityUnits"`; ReservedUnits int `json:"reservedUnits"`; CooledCapacityUnits int `json:"cooledCapacityUnits"`; CooledReservedUnits int `json:"cooledReservedUnits"` }
type Location struct { ID string `json:"id"`; Name string `json:"name"`; Coordinate Coord `json:"coordinate"`; Coverage float64 `json:"coverageKm"`; Handling int `json:"handlingMinutes"`; Active bool `json:"active"`; Functions map[string]bool `json:"functions"`; Capacity Capacity `json:"capacity"`; Accepted []string `json:"acceptedSampleTypeIds"` }
type Connection struct { ID string `json:"id"`; From string `json:"fromLocationId"`; To string `json:"toLocationId"`; Travel int `json:"travelMinutes"`; Cost float64 `json:"costUnits"`; Cooled bool `json:"cooled"`; Active bool `json:"active"`; Capacity Capacity `json:"capacity"` }
type Event struct { ID int `json:"eventId"`; Action string `json:"action"`; Actor string `json:"actorId"`; Role string `json:"role"`; EntityType string `json:"entityType"`; EntityID string `json:"entityId"`; Success bool `json:"success"`; At string `json:"occurredAt"`; Details map[string]interface{} `json:"details"` }
type Sample struct { ID string `json:"id"`; RequestID string `json:"requestId"`; Requester string `json:"requesterId"`; Origin Coord `json:"origin"`; OriginType string `json:"originType"`; OriginNode string `json:"originNodeId,omitempty"`; RequestedAt string `json:"requestedAt"`; Deadline string `json:"deliveryDeadline"`; Earliest string `json:"earliestCollectionAt,omitempty"`; Latest string `json:"latestCollectionAt,omitempty"`; TypeID string `json:"sampleTypeId"`; Container string `json:"containerType"`; Min float64 `json:"temperatureMinC"`; Max float64 `json:"temperatureMaxC"`; Incompatible []string `json:"incompatibleSampleTypes"`; Status string `json:"status"`; Serviceability string `json:"serviceability"`; Sealed bool `json:"sealed"`; Holder string `json:"holder,omitempty"`; JourneyID string `json:"journeyId,omitempty"`; LabID string `json:"labId,omitempty"`; Location *Coord `json:"location,omitempty"`; LocationAt string `json:"locationAt,omitempty"`; Exception map[string]interface{} `json:"exception,omitempty"`; Timeline []Event `json:"timeline"`; Completed []string `json:"completed"`; PendingHandoff string `json:"pendingHandoff,omitempty"` }
type Assignment struct { ID string `json:"id"`; JourneyID string `json:"journeyId"`; SampleID string `json:"sampleId"`; Kind string `json:"kind"`; Status string `json:"status"`; Worker string `json:"workerId,omitempty"`; From string `json:"fromLocationId,omitempty"`; To string `json:"toLocationId,omitempty"`; Seq int `json:"sequence"`; OfferExpires string `json:"offerExpiresAt,omitempty"`; History []Event `json:"history"`; Locations []Coord `json:"locations"`; LastSeq int `json:"lastSeq"` }
type Journey struct { ID string `json:"id"`; Parent string `json:"parent,omitempty"`; Version int `json:"version"`; Mode string `json:"mode"`; Status string `json:"status"`; SampleIDs []string `json:"sampleIds"`; Stops []map[string]interface{} `json:"stops"`; AssignmentIDs []string `json:"assignmentIds"`; ETA string `json:"eta"`; Cost float64 `json:"cost"`; Valid bool `json:"valid"` }
type Handoff struct { ID string `json:"id"`; SampleID string `json:"sampleId"`; From string `json:"fromAssignmentId"`; To string `json:"toAssignmentId"`; Sender string `json:"sender"`; Receiver string `json:"receiver"`; SenderConfirmed bool `json:"senderConfirmed"`; ReceiverConfirmed bool `json:"receiverConfirmed"`; At string `json:"initiatedAt"` }
type State struct { Users map[string]*User `json:"users"`; Types map[string]*SampleType `json:"types"`; Locations map[string]*Location `json:"locations"`; Connections map[string]*Connection `json:"connections"`; Samples map[string]*Sample `json:"samples"`; Journeys map[string]*Journey `json:"journeys"`; Assignments map[string]*Assignment `json:"assignments"`; Handoffs map[string]*Handoff `json:"handoffs"`; Audit []Event `json:"audit"`; NextEvent int `json:"nextEvent"`; Sessions map[string]string `json:"sessions"`; Idempotency map[string]interface{} `json:"idempotency"` }
type App struct { mu sync.Mutex; state State; file string }

func uid() string { b:=make([]byte,16); rand.Read(b); return fmt.Sprintf("%s-%s-4%s-8%s-%s",hex.EncodeToString(b[:4]),hex.EncodeToString(b[4:6]),hex.EncodeToString(b[6:8]),hex.EncodeToString(b[8:10]),hex.EncodeToString(b[10:])) }
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func main(){ a:=&App{file:os.Getenv("STATE_FILE")}; if a.file=="" { a.file="/workspace/data/state.json" }; a.load(); a.seedAdmin(); mux:=http.NewServeMux(); mux.HandleFunc("/ready",a.ready); mux.HandleFunc("/api/",a.api); mux.HandleFunc("/",a.web); fmt.Println("Lab pickup listening on 127.0.0.1:8080"); http.ListenAndServe("127.0.0.1:8080",mux) }
func empty() State { return State{map[string]*User{},map[string]*SampleType{},map[string]*Location{},map[string]*Connection{},map[string]*Sample{},map[string]*Journey{},map[string]*Assignment{},map[string]*Handoff{},[]Event{},1,map[string]string{},map[string]interface{}{}} }
