type Coord struct { Latitude float64 `json:"latitude"`; Longitude float64 `json:"longitude"` }
type User struct { ID string `json:"id"`; Username string `json:"username"`; Password string `json:"password"`; Email string `json:"email,omitempty"`; FullName string `json:"fullName,omitempty"`; Phone string `json:"phone,omitempty"`; Roles []string `json:"roles"`; Qualifications []string `json:"qualifications"`; Certifications []map[string]interface{} `json:"certifications"`; Active bool `json:"active"`; AssignedLocationID string `json:"assignedLocationId,omitempty"`; Available bool `json:"available"`; CapacityUnits int `json:"capacityUnits"`; Location *Coord `json:"location,omitempty"`; LocationAt string `json:"locationAt,omitempty"`; Declines int `json:"declines"` }
