func respond(w http.ResponseWriter,status int,v interface{}){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);json.NewEncoder(w).Encode(v)}
func err(w http.ResponseWriter,s int,code,msg string){respond(w,s,map[string]string{"error":msg,"code":code})}
func decode(w http.ResponseWriter,r *http.Request) (map[string]interface{},bool){ defer r.Body.Close(); var v map[string]interface{}; if json.NewDecoder(io.LimitReader(r.Body,1<<20)).Decode(&v)!=nil {err(w,400,"invalid_request","Invalid JSON request body");return nil,false}; return v,true }
