func stale(at string)bool{t,e:=time.Parse(time.RFC3339,at);return at==""||e!=nil||time.Since(t)>15*time.Minute}
func haversine(a,b Coord)float64{const r=6371;dlat:=(b.Latitude-a.Latitude)*math.Pi/180;dlon:=(b.Longitude-a.Longitude)*math.Pi/180;x:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(a.Latitude*math.Pi/180)*math.Cos(b.Latitude*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2);return 2*r*math.Atan2(math.Sqrt(x),math.Sqrt(1-x))}
func (a *App) eligible(role string, typ *SampleType, location string)*User {us:=[]*User{};for _,u:=range a.state.Users{if !u.Active||!u.Available{continue};has:=false;for _,r:=range u.Roles{if r==role{has=true}};if !has{continue};if (role=="node_handler"||role=="laboratory_team")&&u.AssignedLocationID!=location{continue};if role=="collection_professional"&&typ.Qualified&&!contains(u.Qualifications,typ.Qualification){continue};us=append(us,u)};sort.Slice(us,func(i,j int)bool{return a.workload(us[i].ID)+us[i].Declines< a.workload(us[j].ID)+us[j].Declines});if len(us)==0{return nil};return us[0]}
