 a.mu.Lock(); defer a.mu.Unlock(); p:=strings.TrimPrefix(r.URL.Path,"/api/")
 if p=="authenticate-user" { a.login(w,r); return }
 if p=="events" { if _,_,ok:=a.auth(w,r);ok {respond(w,200,[]map[string]interface{}{})};return }
 if p=="ui/bootstrap" {u,role,ok:=a.auth(w,r);if ok{respond(w,200,a.bootstrap(u,role))};return}
 u,role,ok:=a.auth(w,r);if !ok{return}
 switch p {
 case "select-active-role": a.selectRole(w,r,u,role)
 case "create-user": a.createUser(w,r,u,role)
 case "update-user-access": a.updateUser(w,r,u,role)
 case "create-sample-type":a.sampleType(w,r,u,role,false);case "update-sample-type":a.sampleType(w,r,u,role,true)
 case "create-location":a.location(w,r,u,role,false);case "update-location":a.location(w,r,u,role,true)
 case "create-connection":a.connection(w,r,u,role)
 case "set-location-status", "set-location-function-status", "set-connection-status", "configure-capacity", "configure-laboratory-acceptance", "set-worker-availability": a.configure(w,r,u,role,p)
 case "check-serviceability":a.serviceability(w,r,u,role)
 case "read-serviceability-snapshot":a.snapshot(w,r,u,role)
 case "create-collection-request":a.createRequest(w,r,u,role,false)
 case "ingest-presealed-sample":a.createRequest(w,r,u,role,true)
 case "read-sample-lifecycle":a.lifecycle(w,r,u,role)
 case "read-journey-plan":a.plan(w,r,u,role)
 case "list-role-work":a.roleWork(w,r,u,role)
 case "read-operations-state":a.operations(w,r,u,role)
 case "search-audit-trail":a.searchAudit(w,r,u,role)
 case "accept-assignment", "decline-assignment", "update-assignment-progress", "record-worker-location", "collect-and-seal-sample", "record-handling-checkpoint", "initiate-handoff", "confirm-handoff", "confirm-laboratory-receipt", "record-laboratory-exception": a.workerAction(w,r,u,role,p)
 case "cancel-journey", "reroute-journey", "report-disruption", "edit-active-plan", "split-journey", "merge-journeys": a.planAction(w,r,u,role,p)
 default:
  if strings.HasPrefix(p,"read-sample-state/"){a.sampleState(w,r,u,role,strings.TrimPrefix(p,"read-sample-state/"))
  }else if strings.HasPrefix(p,"read-user/"){a.readUser(w,r,u,role,strings.TrimPrefix(p,"read-user/"))
  }else{err(w,404,"not_found","API operation not found")}
 }
}
func capView(c Capacity) map[string]interface{} {return map[string]interface{}{"capacityUnits":c.CapacityUnits,"reservedUnits":c.ReservedUnits,"availableUnits":c.CapacityUnits-c.ReservedUnits,"cooledCapacityUnits":c.CooledCapacityUnits,"cooledReservedUnits":c.CooledReservedUnits,"cooledAvailableUnits":c.CooledCapacityUnits-c.CooledReservedUnits}}
func locView(l *Location)map[string]interface{}{return map[string]interface{}{"locationId":l.ID,"name":l.Name,"coordinate":l.Coordinate,"coverageKm":l.Coverage,"handlingMinutes":l.Handling,"active":l.Active,"functions":l.Functions}}
func opsLoc(l *Location)map[string]interface{}{v:=locView(l);v["id"]=l.ID;v["capacity"]=capView(l.Capacity);v["acceptedSampleTypeIds"]=l.Accepted;return v}
func stale(at string)bool{t,e:=time.Parse(time.RFC3339,at);return at==""||e!=nil||time.Since(t)>15*time.Minute}
func haversine(a,b Coord)float64{const r=6371;dlat:=(b.Latitude-a.Latitude)*math.Pi/180;dlon:=(b.Longitude-a.Longitude)*math.Pi/180;x:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(a.Latitude*math.Pi/180)*math.Cos(b.Latitude*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2);return 2*r*math.Atan2(math.Sqrt(x),math.Sqrt(1-x))}
func (a *App) eligible(role string, typ *SampleType, location string)*User {us:=[]*User{};for _,u:=range a.state.Users{if !u.Active||!u.Available{continue};has:=false;for _,r:=range u.Roles{if r==role{has=true}};if !has{continue};if (role=="node_handler"||role=="laboratory_team")&&u.AssignedLocationID!=location{continue};if role=="collection_professional"&&typ.Qualified&&!contains(u.Qualifications,typ.Qualification){continue};us=append(us,u)};sort.Slice(us,func(i,j int)bool{return a.workload(us[i].ID)+us[i].Declines< a.workload(us[j].ID)+us[j].Declines});if len(us)==0{return nil};return us[0]}
func (a *App) workload(id string)int{n:=0;for _,x:=range a.state.Assignments{if x.Worker==id&&x.Status!="completed"&&x.Status!="declined"{n++}};return n}
func (a *App) route(origin Coord, originNode, typeID string, deadline string)([]*Connection,*Location,time.Time,bool){ typ:=a.state.Types[typeID];if typ==nil{return nil,nil,time.Time{},false}; starts:=[]*Location{};if originNode!="" {if l:=a.state.Locations[originNode];l!=nil{starts=append(starts,l)}} else {for _,l:=range a.state.Locations{if l.Active&&l.Functions["collection_point"]&&haversine(origin,l.Coordinate)<=l.Coverage{starts=append(starts,l)}}}; if len(starts)==0{return nil,nil,time.Time{},false}; end,er:=time.Parse(time.RFC3339,deadline);if er!=nil{return nil,nil,time.Time{},false};type node struct{l *Location; legs []*Connection; mins int}; q:=[]node{};seen:=map[string]int{};for _,x:=range starts{q=append(q,node{x,nil,x.Handling});seen[x.ID]=x.Handling};for len(q)>0{x:=q[0];q=q[1:];if x.l.Active&&x.l.Functions["laboratory"]&&contains(x.l.Accepted,typeID){eta:=time.Now().Add(time.Duration(x.mins)*time.Minute);if eta.Before(end)&&capacityOK(x.legs,typ){return x.legs,x.l,eta,true}};for _,c:=range a.state.Connections{if c.Active&&c.From==x.l.ID&&(!typ.Cooled||c.Cooled){n:=x.mins+c.Travel;if old,ok:=seen[c.To];!ok||n<old{if dest:=a.state.Locations[c.To];dest!=nil&&dest.Active{seen[c.To]=n;q=append(q,node{dest,append(append([]*Connection{},x.legs...),c),n+dest.Handling})}}}}};return nil,nil,time.Time{},false}
func capacityOK(legs []*Connection,t *SampleType)bool{for _,c:=range legs{if t.Cooled{if !c.Cooled||c.Capacity.CooledReservedUnits>=c.Capacity.CooledCapacityUnits{return false}}else if c.Capacity.ReservedUnits>=c.Capacity.CapacityUnits{return false}};return true}
func contains(xs []string,x string)bool{for _,a:=range xs{if a==x{return true}};return false}

