func (a *App) createRequest(w http.ResponseWriter,r *http.Request,u *User,role string,presealed bool){if presealed {if role!="collection_professional"&&role!="delivery_partner"&&role!="node_handler"&&role!="laboratory_team"&&role!="administrator"{err(w,403,"forbidden","A current custodian must register a pre-sealed sample");return}}else if role!="requester"&&role!="administrator"{err(w,403,"forbidden","Requester role required");return};v,ok:=decode(w,r);if !ok{return};c,g:=coord(v["origin"]);typ:=a.state.Types[str(v,"sampleTypeId")];if !g||typ==nil||str(v,"requestedAt")==""||str(v,"deliveryDeadline")==""||str(v,"containerType")==""||v["temperatureMinC"]==nil||v["temperatureMaxC"]==nil{err(w,400,"validation_error","Required request fields are missing or invalid");return};originType:=str(v,"originType");if originType==""{originType="home"};if presealed&&originType=="home"{err(w,400,"validation_error","Pre-sealed samples cannot originate from a home");return};legs,lab,eta,good:=a.route(c,str(v,"originNodeId"),typ.ID,str(v,"deliveryDeadline"));if !good{err(w,409,"unserviceable","No valid route, capacity, or deadline-compliant laboratory is available");return};requester:=str(v,"requesterId");if requester==""{requester=u.ID};if role=="requester"&&requester!=u.ID{err(w,403,"forbidden","A requester can create only their own requests");return};s:=&Sample{ID:uid(),RequestID:uid(),Requester:requester,Origin:c,OriginType:originType,OriginNode:str(v,"originNodeId"),RequestedAt:str(v,"requestedAt"),Deadline:str(v,"deliveryDeadline"),Earliest:str(v,"earliestCollectionAt"),Latest:str(v,"latestCollectionAt"),TypeID:typ.ID,Container:str(v,"containerType"),Min:num(v,"temperatureMinC"),Max:num(v,"temperatureMaxC"),Incompatible:stringsV(v["incompatibleSampleTypes"]),Status:map[bool]string{true:"sealed",false:"requested"}[presealed],Serviceability:"serviceable",Sealed:presealed,LabID:lab.ID,Timeline:[]Event{},Completed:[]string{}};if presealed{s.Holder=u.ID;s.Location=&c;s.LocationAt=now