type State struct { Users map[string]*User `json:"users"`; Types map[string]*SampleType `json:"types"`; Locations map[string]*Location `json:"locations"`; Connections map[string]*Connection `json:"connections"`; Samples map[string]*Sample `json:"samples"`; Journeys map[string]*Journey `json:"journeys"`; Assignments map[string]*Assignment `json:"assignments"`; Handoffs map[string]*Handoff `json:"handoffs"`; Audit []Event `json:"audit"`; NextEvent int `json:"nextEvent"`; Sessions map[string]string `json:"sessions"`; Idempotency map[string]interface{} `json:"idempotency"` }
type App struct { mu sync.Mutex; state State; file string }

func uid() string { b:=make([]byte,16); rand.Read(b); return fmt.Sprintf("%s-%s-4%s-8%s-%s",hex.EncodeToString(b[:4]),hex.EncodeToString(b[4:6]),hex.EncodeToString(b[6:8]),hex.EncodeToString(b[8:10]),hex.EncodeToString(b[10:])) }
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func main(){ a:=&App{file:os.Getenv("STATE_FILE")}; if a.file=="" { a.file="/workspace/data/state.json" }; a.load(); a.seedAdmin(); mux:=http.NewServeMux(); mux.HandleFunc("/ready",a.ready); mux.HandleFunc("/api/",a.api); mux.HandleFunc("/",a.web); fmt.Println("Lab pickup listening on 127.0.0.1:8080"); http.ListenAndServe("127.0.0.1:8080",mux) }
func empty() State { return State{map[string]*User{},map[string]*SampleType{},map[string]*Location{},map[string]*Connection{},map[string]*Sample{},map[string]*Journey{},map[string]*Assignment{},map[string]*Handoff{},[]Event{},1,map[string]string{},map[string]interface{}{}} }
func (a *App) load(){ a.state=empty(); b,e:=os.ReadFile(a.file); if e==nil { json.Unmarshal(b,&a.state) }; if a.state.Users==nil { a.state=empty() } }
func (a *App) save(){ os.MkdirAll(filepath.Dir(a.file),0755); b,_:=json.MarshalIndent(a.state,"","  "); os.WriteFile(a.file,b,0600) }
func (a *App) seedAdmin(){ a.mu.Lock(); defer a.mu.Unlock(); if len(a.state.Users)>0{return}; un,pw:=os.Getenv("ADMIN_USERNAME"),os.Getenv("ADMIN_PASSWORD"); if un=="" {un="admin"};if pw=="" {pw="admin"}; u:=&User{ID:uid(),Username:un,Password:pw,FullName:"System Administrator",Roles:[]string{"administrator","dispatcher"},Active:true,Available:true,CapacityUnits:1}; a.state.Users[u.ID]=u; for _, x:=range []struct{name,container string;min,max float64; cool,batch bool}{{"Amber","standard",2,25,false,true},{"Indigo","indigo",2,25,false,true},{"Frost","cooled",2,8,true,true},{"Pulse","standard",2,25,false,false}} { id:=uid(); a.state.Types[id]=&SampleType{ID:id,Name:x.name,Qualified:true,Qualification:x.name,Container:x.container,Min:x.min,Max:x.max,Cooled:x.cool,Batching:x.batch,Incompatible:[]string{}} }; a.audit(u,"administrator","bootstrap","system","initialization",true,map[string]interface{}{}); a.save() }
func (a *App) audit(u *User, role, action, typ,id string, success bool, d map[string]interface{}) Event { e:=Event{a.state.NextEvent,action,"",role,typ,id,success,now(),d};a.state.NextEvent++;if u!=nil{e.Actor=u.ID};a.state.Audit=append(a.state.Audit,e); return e }
func respond(w http.ResponseWriter,status int,v interface{}){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);json.NewEncoder(w).Encode(v)}
func err(w http.ResponseWriter,s int,code,msg string){respond(w,s,map[string]string{"error":msg,"code":code})}
func decode(w http.ResponseWriter,r *http.Request) (map[string]interface{},bool){ defer r.Body.Close(); var v map[string]interface{}; if json.NewDecoder(io.LimitReader(r.Body,1<<20)).Decode(&v)!=nil {err(w,400,"invalid_request","Invalid JSON request body");return nil,false}; return v,true }
func str(v map[string]interface{},k string)string{x,_:=v[k].(string);return x};func boolv(v map[string]interface{},k string)bool{x,_:=v[k].(bool);return x};func num(v map[string]interface{},k string)float64{x,_:=v[k].(float64);return x};func intv(v map[string]interface{},k string)int{return int(num(v,k))}
func coord(v interface{})(Coord,bool){m,ok:=v.(map[string]interface{});if !ok{return Coord{},false};lat,ok1:=m["latitude"].(float64);lo,ok2:=m["longitude"].(float64);if !ok1||!ok2||lat < -90||lat>90||lo < -180||lo>180{return Coord{},false};return Coord{lat,lo},true}
func stringsV(v interface{})[]string { arr,_:=v.([]interface{});out:=[]string{};for _,x:=range arr{if s,ok:=x.(string);ok{out=append(out,s)}};return out }
func (a *App) auth(w http.ResponseWriter,r *http.Request, roles ...string)(*User,string,bool){ h:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer ");if h==""{h=r.Header.Get("X-Session-Token")}; id:=a.state.Sessions[h];u:=a.state.Users[id];if u==nil||!u.Active {err(w,401,"unauthenticated","Authentication required");return nil,"",false};role:=r.Header.Get("X-Active-Role");if role=="" {role=u.Roles[0]}; found:=false;for _,x:=range u.Roles{if x==role{found=true}};if !found {err(w,403,"role_not_held","Selected role is not held by this user");return nil,"",false};if len(roles)>0 {ok:=false;for _,z:=range roles{if role==z || role=="administrator"{ok=true}};if !ok {a.audit(u,role,"permission_denied","api",r.URL.Path,false,map[string]interface{}{});a.save();err(w,403,"forbidden","Selected role cannot perform this action");return nil,"",false}};return u,role,true }

func (a *App) ready(w http.ResponseWriter,r *http.Request){ respond(w,200,map[string]string{"status":"ready"}) }
func (a *App) api(w http.ResponseWriter,r *http.Request){
 a.mu.Lock(); defer a.mu.Unlock(); p:=strings.TrimPrefix(r.URL.Path,"/api/")
 if p=="authenticate-user" { a.login(w,r); return }
 if p=="events" { if _,_,ok:=a.auth(w,r);ok {respond(w,200,[]map[string]interface{}{})};return }
 if p=="ui/bootstrap" {u,role,ok:=a.auth(w,r);if ok{respond(w,200,a.bootstrap(u,role))};return}
 u,role,ok:=a.auth(w,r);if !ok{return}
 switch p {
 case "select-active-role": a.selectRole(w,r,u,role)
 case "create-user": a.createUser(w,r,u,role)
 case "update-user-access": a.updateUser(w,r,u,role)
 case "create-sample-type":a.sampleType(w,r,u,role,false);case "update-sample-type":a.sampleType(w,r,u,role,true)
 case "create-location":a.location(w,r,u,role,false);case "update-location":a.location(w,r,u,role,true)
 case "create-connection":a.connection(w,r,u,role)
 case "set-location-status", "set-location-function-status", "set-connection-status", "configure-capacity", "configure-laboratory-acceptance", "set-worker-availability": a.configure(w,r,u,role,p)
 case "check-serviceability":a.serviceability(w,r,u,role)
 case "read-serviceability-snapshot":a.snapshot(w,r,u,role)
 case "create-collection-request":a.createRequest(w,r,u,role,false)
 case "ingest-presealed-sample":a.createRequest(w,r,u,role,true)
 case "read-sample-lifecycle":a.lifecycle(w,r,u,role)
 case "read-journey-plan":a.plan(w,r,u,role)
 case "list-role-work":a.roleWork(w,r,u,role)
 case "read-operations-state":a.operations(w,r,u,role)
 case "search-audit-trail":a.searchAudit(w,r,u,role)
 case "accept-assignment", "decline-assignment", "update-assignment-progress", "record-worker-location", "collect-and-seal-sample", "record-handling-checkpoint", "initiate-handoff", "confirm-handoff", "confirm-laboratory-receipt", "record-laboratory-exception": a.workerAction(w,r,u,role,p)
 case "cancel-journey", "reroute-journey", "report-disruption", "edit-active-plan", "split-journey", "merge-journeys": a.planAction(w,r,u,role,p)
 default:
  if strings.HasPrefix(p,"read-sample-state/"){a.sampleState(w,r,u,role,strings.TrimPrefix(p,"read-sample-state/"))
  }else if strings.HasPrefix(p,"read-user/"){a.readUser(w,r,u,role,strings.TrimPrefix(p,"read-user/"))
  }else{err(w,404,"not_found","API operation not found")}
 }
}
func capView(c Capacity) map[string]interface{} {return map[string]interface{}{"capacityUnits":c.CapacityUnits,"reservedUnits":c.ReservedUnits,"availableUnits":c.CapacityUnits-c.ReservedUnits,"cooledCapacityUnits":c.CooledCapacityUnits,"cooledReservedUnits":c.CooledReservedUnits,"cooledAvailableUnits":c.CooledCapacityUnits-c.CooledReservedUnits}}
func locView(l *Location)map[string]interface{}{return map[string]interface{}{"locationId":l.ID,"name":l.Name,"coordinate":l.Coordinate,"coverageKm":l.Coverage,"handlingMinutes":l.Handling,"active":l.Active,"functions":l.Functions}}
func opsLoc(l *Location)map[string]interface{}{v:=locView(l);v["id"]=l.ID;v["capacity"]=capView(l.Capacity);v["acceptedSampleTypeIds"]=l.Accepted;return v}
func stale(at string)bool{t,e:=time.Parse(time.RFC3339,at);return at==""||e!=nil||time.Since(t)>15*time.Minute}
func haversine(a,b Coord)float64{const r=6371;dlat:=(b.Latitude-a.Latitude)*math.Pi/180;dlon:=(b.Longitude-a.Longitude)*math.Pi/180;x:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(a.Latitude*math.Pi/180)*math.Cos(b.Latitude*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2);return 2*r*math.Atan2(math.Sqrt(x),math.Sqrt(1-x))}
func (a *App) eligible(role string, typ *SampleType, location string)*User {us:=[]*User{};for _,u:=range a.state.Users{if !u.Active||!u.Available{continue};has:=false;for _,r:=range u.Roles{if r==role{has=true}};if !has{continue};if (role=="node_handler"||role=="laboratory_team")&&u.AssignedLocationID!=location{continue};if role=="collection_professional"&&typ.Qualified&&!contains(u.Qualifications,typ.Qualification){continue};us=append(us,u)};sort.Slice(us,func(i,j int)bool{return a.workload(us[i].ID)+us[i].Declines< a.workload(us[j].ID)+us[j].Declines});if len(us)==0{return nil};return us[0]}
func (a *App) workload(id string)int{n:=0;for _,x:=range a.state.Assignments{if x.Worker==id&&x.Status!="completed"&&x.Status!="declined"{n++}};return n}
func (a *App) route(origin Coord, originNode, typeID string, deadline string)([]*Connection,*Location,time.Time,bool){ typ:=a.state.Types[typeID];if typ==nil{return nil,nil,time.Time{},false}; starts:=[]*Location{};if originNode!="" {if l:=a.state.Locations[originNode];l!=nil{starts=append(starts,l)}} else {for _,l:=range a.state.Locations{if l.Active&&l.Functions["collection_point"]&&haversine(origin,l.Coordinate)<=l.Coverage{starts=append(starts,l)}}}; if len(starts)==0{return nil,nil,time.Time{},false}; end,er:=time.Parse(time.RFC3339,deadline);if er!=nil{return nil,nil,time.Time{},false};type node struct{l *Location; legs []*Connection; mins int}; q:=[]node{};seen:=map[string]int{};for _,x:=range starts{q=append(q,node{x,nil,x.Handling});seen[x.ID]=x.Handling};for len(q)>0{x:=q[0];q=q[1:];if x.l.Active&&x.l.Functions["laboratory"]&&contains(x.l.Accepted,typeID){eta:=time.Now().Add(time.Duration(x.mins)*time.Minute);if eta.Before(end)&&capacityOK(x.legs,typ){return x.legs,x.l,eta,true}};for _,c:=range a.state.Connections{if c.Active&&c.From==x.l.ID&&(!typ.Cooled||c.Cooled){n:=x.mins+c.Travel;if old,ok:=seen[c.To];!ok||n<old{if dest:=a.state.Locations[c.To];dest!=nil&&dest.Active{seen[c.To]=n;q=append(q,node{dest,append(append([]*Connection{},x.legs...),c),n+dest.Handling})}}}}};return nil,nil,time.Time{},false}
func capacityOK(legs []*Connection,t *SampleType)bool{for _,c:=range legs{if t.Cooled{if !c.Cooled||c.Capacity.CooledReservedUnits>=c.Capacity.CooledCapacityUnits{return false}}else if c.Capacity.ReservedUnits>=c.Capacity.CapacityUnits{return false}};return true}
func contains(xs []string,x string)bool{for _,a:=range xs{if a==x{return true}};return false}

func (a *App) login(w http.ResponseWriter,r *http.Request){v,ok:=decode(w,r);if !ok{return};for _,u:=range a.state.Users{if u.Username==str(v,"username")&&u.Password==str(v,"password")&&u.Active{t:=uid();a.state.Sessions[t]=u.ID;a.audit(u,u.Roles[0],"sign_in","user",u.ID,true,map[string]interface{}{});a.save();respond(w,200,map[string]interface{}{"token":t,"userId":u.ID,"roles":u.Roles,"activeRole":u.Roles[0]});return}};err(w,401,"invalid_credentials","Username or password is invalid")}
func (a *App) selectRole(w http.ResponseWriter,r *http.Request,u *User,current string){v,ok:=decode(w,r);if !ok{return};role:=str(v,"role");if !contains(u.Roles,role){err(w,403,"role_not_held","Selected role is not held by this user");return};a.audit(u,current,"select_active_role","user",u.ID,true,map[string]interface{}{"role":role});a.save();respond(w,200,map[string]interface{}{"userId":u.ID,"activeRole":role,"roles":u.Roles})}
func (a *App) createUser(w http.ResponseWriter,r *http.Request,u *User,role string){if role!="administrator"{err(w,403,"forbidden","Administrator role required");return};v,ok:=decode(w,r);if !ok{return};if str(v,"username")==""||str(v,"initialPassword")==""||len(stringsV(v["roles"]))==0{err(w,400,"validation_error","Username, password, and roles are required");return};for _,x:=range a.state.Users{if x.Username==str(v,"username"){err(w,409,"conflict","Username already exists");return}};n:=&User{ID:uid(),Username:str(v,"username"),Password:str(v,"initialPassword"),Email:str(v,"email"),FullName:str(v,"fullName"),Phone:str(v,"phone"),Roles:stringsV(v["roles"]),Qualifications:stringsV(v["qualifications"]),Active:boolv(v,"active"),AssignedLocationID:str(v,"assignedLocationId"),Available:true,CapacityUnits:1};a.state.Users[n.ID]=n;a.audit(u,role,"create_user","user",n.ID,true,map[string]interface{}{});a.save();respond(w,201,userView(n))}
func userView(x *User)map[string]interface{}{return map[string]interface{}{"userId":x.ID,"username":x.Username,"email":x.Email,"fullName":x.FullName,"phone":x.Phone,"roles":x.Roles,"qualifications":x.Qualifications,"certifications":x.Certifications,"active":x.Active,"assignedLocationId":x.AssignedLocationID,"available":x.Available,"capacityUnits":x.CapacityUnits}}
