func (a *App) createRequest(w http.ResponseWriter, r *http.Request, u *User, role string, presealed bool) {
	if presealed {
		if role != "collection_professional" && role != "delivery_partner" && role != "node_handler" && role != "laboratory_team" && role != "administrator" {
			err(w, 403, "forbidden", "A current custodian must register a pre-sealed sample")
			return
		}
	} else if role != "requester" && role != "administrator" {
		err(w, 403, "forbidden", "Requester role required")
		return
	}
	v, ok := decode(w, r)
	if !ok {
		return
	}
	c, g := coord(v["origin"])
	typ := a.state.Types[str(v, "sampleTypeId")]
	if !g || typ == nil || str(v, "requestedAt") == "" || str(v, "deliveryDeadline") == "" || str(v, "containerType") == "" || v["temperatureMinC"] == nil || v["temperatureMaxC"] == nil {
		err(w, 400, "validation_error", "Required request fields are missing or invalid")
		return
	}
	originType := str(v, "originType")
	if originType == "" {
		originType = "home"
	}
	if presealed && originType == "home" {
		err(w, 400, "validation_error", "Pre-sealed samples cannot originate from a home")
		return
	}
	legs, lab, eta, good := a.route(c, str(v, "originNodeId"), typ.ID, str(v, "deliveryDeadline"))
	if !good {
		err(w, 409, "unserviceable", "No valid route, capacity, or deadline-compliant laboratory is available")
		return
	}
	requester := str(v, "requesterId")
	if requester == "" {
		requester = u.ID
	}
	if role == "requester" && requester != u.ID {
		err(w, 403, "forbidden", "A requester can create only their own requests")
		return
	}
	s := &Sample{ID: uid(), RequestID: uid(), Requester: requester, Origin: c, OriginType: originType, OriginNode: str(v, "originNodeId"), RequestedAt: str(v, "requestedAt"), Deadline: str(v, "deliveryDeadline"), Earliest: str(v, "earliestCollectionAt"), Latest: str(v, "latestCollectionAt"), TypeID: typ.ID, Container: str(v, "containerType"), Min: num(v, "temperatureMinC"), Max: num(v, "temperatureMaxC"), Incompatible: stringsV(v["incompatibleSampleTypes"]), Status: map[bool]string{true: "sealed", false: "requested"}[presealed], Serviceability: "serviceable", Sealed: presealed, LabID: lab.ID, Timeline: []Event{}, Completed: []string{}}
	if presealed {
		s.Holder = u.ID
		s.Location = &c
		s.LocationAt = now()
	}
	a.state.Samples[s.ID] = s
	j := &Journey{ID: uid(), Version: 1, Mode: map[bool]string{true: "direct", false: "multi_stop"}[len(legs) <= 1], Status: "planned", SampleIDs: []string{s.ID}, Stops: []map[string]interface{}{}, AssignmentIDs: []string{}, ETA: eta.Format(time.RFC3339), Valid: true}
	s.JourneyID = j.ID
	start := s.OriginNode
	if start == "" && len(legs) > 0 {
		start = legs[0].From
	}
	if !presealed {
		a.offer(j, s, "collection", uOrNil(a.eligible("collection_professional", typ, "")), "", start, 0)
	}
	for i, cx := range legs {
		a.reserve(cx, typ)
		a.offer(j, s, "transport", uOrNil(a.eligible("delivery_partner", typ, "")), cx.From, cx.To, i+1)
		j.Stops = append(j.Stops, map[string]interface{}{"stopId": uid(), "locationId": cx.To, "stopType": map[bool]string{i == len(legs)-1: "delivery", i != len(legs)-1: "handoff"}[true], "sequence": i + 1, "estimatedAt": time.Now().Add(time.Duration((i+1)*cx.Travel) * time.Minute).Format(time.RFC3339)})
	}
	a.offer(j, s, "laboratory", uOrNil(a.eligible("laboratory_team", typ, lab.ID)), start, lab.ID, len(legs)+1)
	a.state.Journeys[j.ID] = j
	e := a.audit(u, role, map[bool]string{true: "ingest_presealed_sample", false: "create_collection_request"}[presealed], "sample", s.ID, true, map[string]interface{}{"journeyId": j.ID})
	s.Timeline = append(s.Timeline, e)
	a.save()
	respond(w, 201, a.sampleView(s))
}
func uOrNil(u *User) string {
	if u == nil {
		return ""
	}
	return u.ID
}
func (a *App) offer(j *Journey, s *Sample, kind, worker, from, to string, seq int) {
	x := &Assignment{ID: uid(), JourneyID: j.ID, SampleID: s.ID, Kind: kind, Status: "offered", Worker: worker, From: from, To: to, Seq: seq, OfferExpires: time.Now().Add(10 * time.Minute).Format(time.RFC3339), History: []Event{}, Locations: []Coord{}}
	if worker == "" {
		x.Status = "exception"
		s.Exception = map[string]interface{}{"reason": "no_qualified_worker_available", "assignmentKind": kind}
		s.Status = "exception"
	}
	a.state.Assignments[x.ID] = x
	j.AssignmentIDs = append(j.AssignmentIDs, x.ID)
	e := a.audit(nil, "system", "assignment_offered", "assignment", x.ID, worker != "", map[string]interface{}{"workerId": worker, "kind": kind})
	x.History = append(x.History, e)
	s.Timeline = append(s.Timeline, e)
}
