func (a *App) lifecycle(w http.ResponseWriter, r *http.Request, u *User, role string) {
	v, ok := decode(w, r)
	if !ok {
		return
	}
	s := a.state.Samples[str(v, "sampleId")]
	if s == nil {
		err(w, 404, "not_found", "Sample not found")
