	for _, l := range a.state.Locations {
		if l.Active && l.Functions["collection_point"] {
			regions = append(regions, map[string]interface{}{"locationId": l.ID, "name": l.Name, "latitude": l.Coordinate.Latitude, "longitude": l.Coordinate.Longitude, "coverageKm": l.Coverage})
		}
	}
	respond(w, 200, map[string]interface{}{"serviceable": good, "reason": map[bool]string{true: "network_route_available", false: "no_active_capacity_aware_route"}[good], "targetLaboratoryId": func() string {
		if lab != nil {
			return lab.ID
		}
		return ""
	}(), "estimatedDeliveryAt": eta.Format(time.RFC3339), "serviceabilityVersion": 1, "regions": regions})
}
