		return false
	}
	if s.Earliest != "" {
		x, _ := time.Parse(time.RFC3339, s.Earliest)
		if t.Before(x) {
			return false
		}
	}
	if s.Latest != "" {
		x, _ := time.Parse(time.RFC3339, s.Latest)
		if t.After(x) {
			return false
		}
	}
