	legs := []map[string]interface{}{}
	workers := []string{}
	for _, id := range j.AssignmentIDs {
		x := a.state.Assignments[id]
		if x == nil {
			continue
		}
		if worker != "" && x.Worker != worker {
			continue
		}
		z := map[string]interface{}{"assignmentId": x.ID, "sequence": x.Seq, "status": x.Status}
		if x.From != "" {
			z["fromLocationId"] = x.From
		}
		if x.To != "" {
			z["toLocationId"] = x.To
		}
		if x.Worker != "" {
			z["workerId"] = x.Worker
			workers = append(workers, x.Worker)
		}
		z["sampleId"] = x.SampleID
		legs = append(legs, z)
	}
	return map[string]interface{}{"journeyId": j.ID, "planVersion": j.Version, "routeMode": j.Mode, "status": j.Status, "estimatedDeliveryAt": j.ETA, "totalCostUnits": j.Cost, "capacityUsed": len(j.SampleIDs), "capacityAvailable": 0, "sampleIds": j.SampleIDs, "orderedStops": j.Stops, "legs": legs, "assignedWorkerIds": workers, "valid": j.Valid, "replanStatus": "not_required"}
