func stale(at string) bool {
	t, e := time.Parse(time.RFC3339, at)
	return at == "" || e != nil || time.Since(t) > 15*time.Minute
}
func haversine(a, b Coord) float64 {
	const r = 6371
	dlat := (b.Latitude - a.Latitude) * math.Pi / 180
	dlon := (b.Longitude - a.Longitude) * math.Pi / 180
	x := math.Sin(dlat/2)*math.Sin(dlat/2) + math.Cos(a.Latitude*math.Pi/180)*math.Cos(b.Latitude*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2)
	return 2 * r * math.Atan2(math.Sqrt(x), math.Sqrt(1-x))
}
func (a *App) eligible(role string, typ *SampleType, location string) *User {
	us := []*User{}
	for _, u := range a.state.Users {
		if !u.Active || !u.Available {
			continue
		}
		has := false
		for _, r := range u.Roles {
			if r == role {
				has = true
			}
		}
		if !has {
			continue
		}
		if (role == "node_handler" || role == "laboratory_team") && u.AssignedLocationID != location {
			continue
		}
		if role == "collection_professional" && typ.Qualified && !contains(u.Qualifications, typ.Qualification) {
			continue
		}
		us = append(us, u)
	}
	sort.Slice(us, func(i, j int) bool { return a.workload(us[i].ID)+us[i].Declines < a.workload(us[j].ID)+us[j].Declines })
	if len(us) == 0 {
		return nil
	}
	return us[0]
}
func (a *App) workload(id string) int {
	n := 0
	for _, x := range a.state.Assignments {
		if x.Worker == id && x.Status != "completed" && x.Status != "declined" {
			n++
		}
	}
	return n
}
func (a *App) route(origin Coord, originNode, typeID string, deadline string) ([]*Connection, *Location, time.Time, bool) {
	typ := a.state.Types[typeID]
	if typ == nil {
		return nil, nil, time.Time{}, false
	}
	starts := []*Location{}
	if originNode != "" {
		if l := a.state.Locations[originNode]; l != nil {
			starts = append(starts, l)
		}
	} else {
		for _, l := range a.state.Locations {
			if l.Active && l.Functions["collection_point"] && haversine(origin, l.Coordinate) <= l.Coverage {
				starts = append(starts, l)
			}
		}
	}
	if len(starts) == 0 {
		return nil, nil, time.Time{}, false
	}
	end, er := time.Parse(time.RFC3339, deadline)
	if er != nil {
		return nil, nil, time.Time{}, false
	}
	type node struct {
		l    *Location
		legs []*Connection
		mins int
	}
	q := []node{}
	seen := map[string]int{}
	for _, x := range starts {
		q = append(q, node{x, nil, x.Handling})
		seen[x.ID] = x.Handling
	}
	for len(q) > 0 {
		x := q[0]
		q = q[1:]
		if x.l.Active && x.l.Functions["laboratory"] && contains(x.l.Accepted, typeID) {
			eta := time.Now().Add(time.Duration(x.mins) * time.Minute)
			if eta.Before(end) && capacityOK(x.legs, typ) {
				return x.legs, x.l, eta, true
			}
		}
		for _, c := range a.state.Connections {
			if c.Active && c.From == x.l.ID && (!typ.Cooled || c.Cooled) {
				n := x.mins + c.Travel
				if old, ok := seen[c.To]; !ok || n < old {
					if dest := a.state.Locations[c.To]; dest != nil && dest.Active {
						seen[c.To] = n
						q = append(q, node{dest, append(append([]*Connection{}, x.legs...), c), n + dest.Handling})
					}
				}
			}
		}
	}
	return nil, nil, time.Time{}, false
}
func capacityOK(legs []*Connection, t *SampleType) bool {
	for _, c := range legs {
		if t.Cooled {
			if !c.Cooled || c.Capacity.CooledReservedUnits >= c.Capacity.CooledCapacityUnits {
				return false
			}
		} else if c.Capacity.ReservedUnits >= c.Capacity.CapacityUnits {
			return false
		}
	}
	return true
}
func contains(xs []string, x string) bool {
	for _, a := range xs {
		if a == x {
			return true
		}
	}
	return false
}

func (a *App) login(w http.ResponseWriter, r *http.Request) {
	v, ok := decode(w, r)
	if !ok {
		return
	}
	for _, u := range a.state.Users {
		if u.Username == str(v, "username") && u.Password == str(v, "password") && u.Active {
			t := uid()
			a.state.Sessions[t] = u.ID
			a.audit(u, u.Roles[0], "sign_in", "user", u.ID, true, map[string]interface{}{})
			a.save()
			respond(w, 200, map[string]interface{}{"token": t, "userId": u.ID, "roles": u.Roles, "activeRole": u.Roles[0]})
			return
		}
	}
	err(w, 401, "invalid_credentials", "Username or password is invalid")
}
func (a *App) selectRole(w http.ResponseWriter, r *http.Request, u *User, current string) {
	v, ok := decode(w, r)
	if !ok {
		return
	}
	role := str(v, "role")
	if !contains(u.Roles, role) {
		err(w, 403, "role_not_held", "Selected role is not held by this user")
		return
	}
	a.audit(u, current, "select_active_role", "user", u.ID, true, map[string]interface{}{"role": role})
	a.save()
	respond(w, 200, map[string]interface{}{"userId": u.ID, "activeRole": role, "roles": u.Roles})
}
func (a *App) createUser(w http.ResponseWriter, r *http.Request, u *User, role string) {
	if role != "administrator" {
		err(w, 403, "forbidden", "Administrator role required")
		return
	}
	v, ok := decode(w, r)
	if !ok {
		return
	}
	if str(v, "username") == "" || str(v, "initialPassword") == "" || len(stringsV(v["roles"])) == 0 {
		err(w, 400, "validation_error", "Username, password, and roles are required")
		return
	}
	for _, x := range a.state.Users {
		if x.Username == str(v, "username") {
			err(w, 409, "conflict", "Username already exists")
			return
		}
	}
	n := &User{ID: uid(), Username: str(v, "username"), Password: str(v, "initialPassword"), Email: str(v, "email"), FullName: str(v, "fullName"), Phone: str(v, "phone"), Roles: stringsV(v["roles"]), Qualifications: stringsV(v["qualifications"]), Active: boolv(v, "active"), AssignedLocationID: str(v, "assignedLocationId"), Available: true, CapacityUnits: 1}
	a.state.Users[n.ID] = n
	a.audit(u, role, "create_user", "user", n.ID, true, map[string]interface{}{})
	a.save()
	respond(w, 201, userView(n))
}
