	ss := []interface{}{}
	for _, s := range a.state.Samples {
		x := map[string]interface{}{"sampleId": s.ID, "status": s.Status, "locationStale": stale(s.LocationAt)}
		if s.Location != nil {
			x["latestLocation"] = s.Location
			x["locationRecordedAt"] = s.LocationAt
		}
		if s.Holder != "" {
			x["currentHolderId"] = s.Holder
		}
		if s.JourneyID != "" {
			x["activeJourneyId"] = s.JourneyID
		}
		ss = append(ss, x)
	}
	ws := []interface{}{}
	for _, x := range a.state.Users {
		if x.ID == u.ID {
			continue
		}
		z := map[string]interface{}{"workerId": x.ID, "fullName": x.FullName, "roles": x.Roles, "available": x.Available, "status": map[bool]string{true: "available", false: "unavailable"}[x.Available], "capacityUnits": x.CapacityUnits, "assignmentCount": a.workload(x.ID), "locationStale": stale(x.LocationAt)}
		if x.Location != nil {
			z["latestLocation"] = x.Location
			z["locationRecordedAt"] = x.LocationAt
		}
		ws = append(ws, z)
	}
	ls := []interface{}{}
	for _, l := range a.state.Locations {
		ls = append(ls, opsLoc(l))
	}
	cs := []interface{}{}
	for _, c := range a.state.Connections {
		cs = append(cs, map[string]interface{}{"id": c.ID, "connectionId": c.ID, "fromLocationId": c.From, "toLocationId": c.To, "travelMinutes": c.Travel, "costUnits": c.Cost, "cooled": c.Cooled, "active": c.Active, "capacity": capView(c.Capacity)})
	}
	ex := []interface{}{}
	for _, s := range a.state.Samples {
		if s.Exception != nil {
			ex = append(ex, map[string]interface{}{"sampleId": s.ID, "exception": s.Exception})
		}
	}
	respond(w, 200, map[string]interface{}{"samples": ss, "workers": ws, "locations": ls, "connections": cs, "routes": []interface{}{}, "handoffs": a.state.Handoffs, "delays": []interface{}{}, "exceptions": ex, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0})
}
func (a *App) searchAudit(w http.ResponseWriter, r *http.Request, u *User, role string) {
	if role != "dispatcher" && role != "administrator" {
		err(w, 403, "forbidden", "Dispatcher role required")
		return
	}
	v, ok := decode(w, r)
	if !ok {
		return
	}
	q := strings.ToLower(str(v, "query"))
	entity := str(v, "entityId")
	action := str(v, "action")
	entries := []interface{}{}
	for i := len(a.state.Audit) - 1; i >= 0; i-- {
		e := a.state.Audit[i]
		if entity != "" && e.EntityID != entity {
			continue
		}
		if action != "" && e.Action != action {
			continue
		}
		if q != "" && !strings.Contains(strings.ToLower(e.Action+e.EntityID+e.EntityType), q) {
			continue
		}
		entries = append(entries, map[string]interface{}{"auditId": fmt.Sprint(e.ID), "actorId": e.Actor, "role": e.Role, "actorRole": e.Role, "action": e.Action, "entityType": e.EntityType, "entityId": e.EntityID, "success": e.Success, "occurredAt": e.At, "details": e.Details})
	}
	limit := intv(v, "limit")
	if limit == 0 {
		limit = 500
	}
	if len(entries) > limit {
		entries = entries[:limit]
	}
	respond(w, 200, map[string]interface{}{"entries": entries, "total": len(entries), "returned": len(entries), "offset": 0, "limit": limit, "order": "newest_first", "hasMore": false})
}
func (a *App) workerAction(w http.ResponseWriter, r *http.Request, u *User, role, p string) {
	v, ok := decode(w, r)
	if !ok {
		return
	}
	if p == "initiate-handoff" || p == "confirm-handoff" {
		a.handoff(w, u, role, p, v)
		return
	}
	if p == "confirm-laboratory-receipt" || p == "record-laboratory-exception" {
		sid := str(v, "sampleId")
		s := a.state.Samples[sid]
		if s == nil {
			err(w, 404, "not_found", "Sample not found")
			return
		}
		if role != "laboratory_team" && role != "administrator" {
			err(w, 403, "forbidden", "Laboratory role required")
			return
		}
		if p == "confirm-laboratory-receipt" {
			s.Status = "received"
			s.Holder = u.ID
			s.LabID = str(v, "laboratoryId")
		} else {
			s.Status = "exception"
			s.Exception = map[string]interface{}{"reason": str(v, "reason"), "laboratoryId": str(v, "laboratoryId")}
		}
		e := a.audit(u, role, p, "sample", sid, true, map[string]interface{}{})
		s.Timeline = append(s.Timeline, e)
		a.save()
		respond(w, 201, a.lifecycleView(s))
		return
	}
	id := str(v, "assignmentId")
	x := a.state.Assignments[id]
	if x == nil {
		err(w, 404, "not_found", "Assignment not found")
		return
	}
	if x.Worker != u.ID && role != "administrator" {
		err(w, 403, "forbidden", "Assignment is offered to another worker")
		return
	}
	s := a.state.Samples[x.SampleID]
	if p == "accept-assignment" {
		if x.Status != "offered" {
			err(w, 409, "assignment_unavailable", "Assignment is no longer offered")
			return
		}
		x.Status = "accepted"
	} else if p == "decline-assignment" {
		x.Status = "declined"
		u.Declines++
		typ := a.state.Types[s.TypeID]
		a.offer(a.state.Journeys[x.JourneyID], s, x.Kind, uOrNil(a.eligible(map[string]string{"collection": "collection_professional", "transport": "delivery_partner", "node": "node_handler", "laboratory": "laboratory_team"}[x.Kind], typ, x.To)), x.From, x.To, x.Seq)
	} else if p == "record-worker-location" {
		c, g := coord(v["coordinate"])
		if !g || intv(v, "sequence") <= x.LastSeq {
			err(w, 409, "location_sequence", "Location sequence must increase")
			return
		}
		x.LastSeq = intv(v, "sequence")
		x.Locations = append(x.Locations, c)
		u.Location = &c
		u.LocationAt = str(v, "recordedAt")
		s.Location = &c
		s.LocationAt = u.LocationAt
	} else if p == "collect-and-seal-sample" {
		if role != "collection_professional" && role != "administrator" {
			err(w, 403, "forbidden", "Collection professional required")
			return
		}
		if !within(s, str(v, "collectedAt")) {
			err(w, 409, "collection_window", "Collection is outside its allowed window")
			return
		}
		s.Sealed = true
		s.Holder = u.ID
		s.Status = "sealed"
		x.Status = "completed"
		s.Completed = append(s.Completed, x.ID)
	} else if p == "record-handling-checkpoint" {
		temp := num(v, "observedTemperatureC")
		if str(v, "containerType") != s.Container || temp < s.Min || temp > s.Max {
			s.Status = "exception"
			s.Exception = map[string]interface{}{"reason": "handling_requirement_violation", "observedTemperatureC": temp, "containerType": str(v, "containerType")}
		}
	} else {
		x.Status = str(v, "status")
		if x.Status == "completed" || x.Status == "delivered" {
			s.Completed = append(s.Completed, x.ID)
		}
	}
	e := a.audit(u, role, p, "assignment", x.ID, true, map[string]interface{}{})
	x.History = append(x.History, e)
	s.Timeline = append(s.Timeline, e)
	a.save()
	respond(w, 201, map[string]interface{}{"assignmentId": x.ID, "status": x.Status, "sampleId": s.ID, "sampleStatus": s.Status})
}
func within(s *Sample, at string) bool {
	t, e := time.Parse(time.RFC3339, at)
	if e != nil {
		return false
	}
	if s.Earliest != "" {
		x, _ := time.Parse(time.RFC3339, s.Earliest)
		if t.Before(x) {
			return false
		}
	}
	if s.Latest != "" {
		x, _ := time.Parse(time.RFC3339, s.Latest)
		if t.After(x) {
			return false
		}
	}
	return true
}
func (a *App) handoff(w http.ResponseWriter, u *User, role, p string, v map[string]interface{}) {
	if p == "initiate-handoff" {
		s := a.state.Samples[str(v, "sampleId")]
		from, to := a.state.Assignments[str(v, "fromAssignmentId")], a.state.Assignments[str(v, "toAssignmentId")]
		if s == nil || from == nil || to == nil {
			err(w, 404, "not_found", "Sample or assignment not found")
			return
		}
		if from.Worker != u.ID && role != "administrator" {
			err(w, 403, "forbidden", "Current sender must initiate handoff")
			return
		}
		h := &Handoff{ID: uid(), SampleID: s.ID, From: from.ID, To: to.ID, Sender: u.ID, Receiver: str(v, "receiverId"), At: str(v, "initiatedAt")}
		a.state.Handoffs[h.ID] = h
		s.PendingHandoff = h.ID
		a.save()
		respond(w, 201, map[string]interface{}{"handoffId": h.ID, "status": "pending", "sampleId": s.ID})
		return
	}
	h := a.state.Handoffs[str(v, "handoffId")]
	if h == nil {
		err(w, 404, "not_found", "Handoff not found")
		return
	}
	side := str(v, "confirmationSide")
	if side == "sender" && h.Sender != u.ID && role != "administrator" {
		err(w, 403, "forbidden", "Sender confirmation required")
		return
	}
	if side == "receiver" && h.Receiver != u.ID && role != "administrator" {
		err(w, 403, "forbidden", "Receiver confirmation required")
		return
	}
	if side == "sender" {
		h.SenderConfirmed = true
	} else {
		h.ReceiverConfirmed = true
	}
	s := a.state.Samples[h.SampleID]
	if h.SenderConfirmed && h.ReceiverConfirmed {
		s.Holder = h.Receiver
		s.PendingHandoff = ""
		s.Status = "in_custody"
	}
	a.save()
	respond(w, 201, map[string]interface{}{"handoffId": h.ID, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed, "currentHolderId": s.Holder})
}
func (a *App) lifecycleView(s *Sample) map[string]interface{} {
	return map[string]interface{}{"sampleId": s.ID, "status": s.Status, "sealed": s.Sealed, "completedLegIds": s.Completed, "activeReplacementPlanIds": []string{}, "timeline": s.Timeline, "locationStale": stale(s.LocationAt)}
}
func (a *App) planAction(w http.ResponseWriter, r *http.Request, u *User, role, p string) {
	if role != "dispatcher" && role != "administrator" {
		err(w, 403, "forbidden", "Dispatcher role required")
		return
	}
	v, ok := decode(w, r)
	if !ok {
		return
	}
	if p == "report-disruption" {
		for _, s := range a.state.Samples {
			if s.Status != "received" && s.Status != "cancelled" {
				s.Exception = map[string]interface{}{"reason": "disruption", "resourceId": str(v, "resourceId")}
			}
		}
		a.audit(u, role, p, "resource", str(v, "resourceId"), true, map[string]interface{}{})
		a.save()
		respond(w, 201, map[string]interface{}{"status": "replan_required"})
		return
	}
	id := str(v, "journeyId")
	if p == "merge-journeys" {
		id = str(v, "targetJourneyId")
	}
	j := a.state.Journeys[id]
	if j == nil {
		err(w, 404, "not_found", "Journey not found")
		return
	}
	if intv(v, "expectedPlanVersion") != j.Version {
		err(w, 409, "plan_version_conflict", "Journey plan was updated by another operation")
		return
	}
	if p == "cancel-journey" {
		j.Status = "cancelled"
		for _, sid := range j.SampleIDs {
			a.state.Samples[sid].Status = "cancelled"
		}
	} else {
		j.Version++
		if p == "reroute-journey" {
			j.Status = "replanned"
		}
	}
	a.audit(u, role, p, "journey", j.ID, true, map[string]interface{}{})
	a.save()
	respond(w, 201, a.planView(j, ""))
}

func (a *App) bootstrap(u *User, role string) map[string]interface{} {
	types := []interface{}{}
	for _, t := range a.state.Types {
		types = append(types, map[string]interface{}{"sampleTypeId": t.ID, "name": t.Name, "containerType": t.Container, "temperatureMinC": t.Min, "temperatureMaxC": t.Max, "requiresCooledRoute": t.Cooled, "batchingAllowed": t.Batching})
	}
	locs := []interface{}{}
	for _, l := range a.state.Locations {
		locs = append(locs, opsLoc(l))
	}
	return map[string]interface{}{"user": userView(u), "activeRole": role, "sampleTypes": types, "locations": locs, "serviceabilityVersion": 1, "map": map[string]interface{}{"provider": "local-pmtiles", "style": "/map/style.json"}}
}
func (a *App) web(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" && r.URL.Path != "/index.html" {
		http.NotFound(w, r)
		return
	}
	b, e := os.ReadFile("/workspace/web/index.html")
	if e != nil {
		http.Error(w, "dashboard build is unavailable", 500)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write(b)
}

