	}
	b, e := os.ReadFile("/workspace/web/index.html")
	if e != nil {
		http.Error(w, "dashboard build is unavailable", 500)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write(b)
}

