	respond(w, 200, map[string]interface{}{"samples": ss, "workers": ws, "locations": ls, "connections": cs, "routes": []interface{}{}, "handoffs": a.state.Handoffs, "delays": []interface{}{}, "exceptions": ex, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0})
