func (a *App) offer(j *Journey, s *Sample, kind, worker, from, to string, seq int) {
	x := &Assignment{ID: uid(), JourneyID: j.ID, SampleID: s.ID, Kind: kind, Status: "offered", Worker: worker, From: from, To: to, Seq: seq, OfferExpires: time.Now().Add(10 * time.Minute).Format(time.RFC3339), History: []Event{}, Locations: []Coord{}}
