			x["activeJourneyId"] = s.JourneyID
		}
		ss = append(ss, x)
	}
	ws := []interface{}{}
	for _, x := range a.state.Users {
		if x.ID == u.ID {
			continue
		}
		z := map[string]interface{}{"workerId": x.ID, "fullName": x.FullName, "roles": x.Roles, "available": x.Available, "status": map[bool]string{true: "available", false: "unavailable"}[x.Available], "capacityUnits": x.CapacityUnits, "assignmentCount": a.workload(x.ID), "locationStale": stale(x.LocationAt)}
		if x.Location != nil {
