func (a *App) audit(u *User, role, action, typ, id string, success bool, d map[string]interface{}) Event {
	e := Event{a.state.NextEvent, action, "", role, typ, id, success, now(), d}
	a.state.NextEvent++
	if u != nil {
		e.Actor = u.ID
	}
	a.state.Audit = append(a.state.Audit, e)
	return e
}
func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

// Every successful application API operation is returned in the pinned data envelope.
func respond(w http.ResponseWriter, status int, v interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": v})
}
func err(w http.ResponseWriter, s int, code, msg string) {
	writeJSON(w, s, map[string]string{"error": msg, "code": code})
}
func decode(w http.ResponseWriter, r *http.Request) (map[string]interface{}, bool) {
	defer r.Body.Close()
	var v map[string]interface{}
	if json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&v) != nil {
		err(w, 400, "invalid_request", "Invalid JSON request body")
		return nil, false
	}
	return v, true
}
func str(v map[string]interface{}, k string) string  { x, _ := v[k].(string); return x }
func boolv(v map[string]interface{}, k string) bool  { x, _ := v[k].(bool); return x }
func num(v map[string]interface{}, k string) float64 { x, _ := v[k].(float64); return x }
func intv(v map[string]interface{}, k string) int    { return int(num(v, k)) }
func coord(v interface{}) (Coord, bool) {
	m, ok := v.(map[string]interface{})
	if !ok {
		return Coord{}, false
	}
	lat, ok1 := m["latitude"].(float64)
	lo, ok2 := m["longitude"].(float64)
	if !ok1 || !ok2 || lat < -90 || lat > 90 || lo < -180 || lo > 180 {
		return Coord{}, false
	}
	return Coord{lat, lo}, true
}
func stringsV(v interface{}) []string {
	arr, _ := v.([]interface{})
	out := []string{}
	for _, x := range arr {
		if s, ok := x.(string); ok {
			out = append(out, s)
		}
	}
	return out
}
func (a *App) auth(w http.ResponseWriter, r *http.Request, roles ...string) (*User, string, bool) {
	h := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	if h == "" {
		h = r.Header.Get("X-Session-Token")
	}
	id := a.state.Sessions[h]
	u := a.state.Users[id]
	if u == nil || !u.Active {
		err(w, 401, "unauthenticated", "Authentication required")
		return nil, "", false
	}
	role := r.Header.Get("X-Active-Role")
	if role == "" {
		role = u.Roles[0]
	}
	found := false
	for _, x := range u.Roles {
		if x == role {
			found = true
		}
	}
	if !found {
		err(w, 403, "role_not_held", "Selected role is not held by this user")
		return nil, "", false
	}
	if len(roles) > 0 {
		ok := false
		for _, z := range roles {
			if role == z || role == "administrator" {
				ok = true
			}
		}
		if !ok {
			a.audit(u, role, "permission_denied", "api", r.URL.Path, false, map[string]interface{}{})
			a.save()
			err(w, 403, "forbidden", "Selected role cannot perform this action")
			return nil, "", false
		}
	}
	return u, role, true
}

func (a *App) ready(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, 200, map[string]string{"status": "ready"})
}
func (a *App) api(w http.ResponseWriter, r *http.Request) {
	a.mu.Lock()
	defer a.mu.Unlock()
	p := strings.TrimPrefix(r.URL.Path, "/api/")
	if p == "authenticate-user" {
		a.login(w, r)
		return
	}
	if p == "events" {
		if _, _, ok := a.auth(w, r); ok {
			respond(w, 200, []map[string]interface{}{})
		}
		return
	}
	if p == "ui/bootstrap" {
		u, role, ok := a.auth(w, r)
		if ok {
			respond(w, 200, a.bootstrap(u, role))
		}
		return
	}
	u, role, ok := a.auth(w, r)
	if !ok {
		return
	}
	switch p {
	case "select-active-role":
		a.selectRole(w, r, u, role)
	case "create-user":
		a.createUser(w, r, u, role)
	case "update-user-access":
		a.updateUser(w, r, u, role)
	case "create-sample-type":
		a.sampleType(w, r, u, role, false)
	case "update-sample-type":
		a.sampleType(w, r, u, role, true)
	case "create-location":
		a.location(w, r, u, role, false)
	case "update-location":
		a.location(w, r, u, role, true)
	case "create-connection":
		a.connection(w, r, u, role)
	case "set-location-status", "set-location-function-status", "set-connection-status", "configure-capacity", "configure-laboratory-acceptance", "set-worker-availability":
		a.configure(w, r, u, role, p)
	case "check-serviceability":
		a.serviceability(w, r, u, role)
	case "read-serviceability-snapshot":
		a.snapshot(w, r, u, role)
	case "create-collection-request":
		a.createRequest(w, r, u, role, false)
	case "ingest-presealed-sample":
		a.createRequest(w, r, u, role, true)
	case "read-sample-lifecycle":
		a.lifecycle(w, r, u, role)
	case "read-journey-plan":
		a.plan(w, r, u, role)
	case "list-role-work":
		a.roleWork(w, r, u, role)
	case "read-operations-state":
		a.operations(w, r, u, role)
	case "search-audit-trail":
		a.searchAudit(w, r, u, role)
	case "accept-assignment", "decline-assignment", "update-assignment-progress", "record-worker-location", "collect-and-seal-sample", "record-handling-checkpoint", "initiate-handoff", "confirm-handoff", "confirm-laboratory-receipt", "record-laboratory-exception":
		a.workerAction(w, r, u, role, p)
	case "cancel-journey", "reroute-journey", "report-disruption", "edit-active-plan", "split-journey", "merge-journeys":
		a.planAction(w, r, u, role, p)
	default:
		if strings.HasPrefix(p, "read-sample-state/") {
			a.sampleState(w, r, u, role, strings.TrimPrefix(p, "read-sample-state/"))
		} else if strings.HasPrefix(p, "read-user/") {
			a.readUser(w, r, u, role, strings.TrimPrefix(p, "read-user/"))
		} else {
			err(w, 404, "not_found", "API operation not found")
		}
	}
}
func capView(c Capacity) map[string]interface{} {
	return map[string]interface{}{"capacityUnits": c.CapacityUnits, "reservedUnits": c.ReservedUnits, "availableUnits": c.CapacityUnits - c.ReservedUnits, "cooledCapacityUnits": c.CooledCapacityUnits, "cooledReservedUnits": c.CooledReservedUnits, "cooledAvailableUnits": c.CooledCapacityUnits - c.CooledReservedUnits}
}
